-- SoenensMedia Portaal — Fase 32b: content-strategie data voor Decaigny Selected Cars & Vans
-- Eenmalig, na sql/025_content_strategie.sql. Vereist dat de klant al bestaat
-- (Klanten-tab, exacte naam "Decaigny Selected Cars & Vans") — anders doet dit script niets.

do $$
declare
  v_client_id uuid;
begin
  select id into v_client_id from clients where naam ilike '%Decaigny%' limit 1;
  if v_client_id is null then
    raise notice 'Geen klant met "Decaigny" in de naam gevonden — maak deze eerst aan in de Klanten-tab.';
    return;
  end if;

  values (v_client_id, 'Multimerk occasies, personen- en bestelwagens', '5 shorts per maand', ARRAY['naambekendheid', 'employer branding']::text[], ARRAY['Particulier 25-55 uit West-Vlaanderen die twijfelt of de garage te vertrouwen is', 'Zelfstandige of kleine KMO die snel een bestelwagen nodig heeft', 'Toekomstige werknemer: mecanicien, carrosserie, magazijn']::text[], 'Niet ''kijk onze auto''s'', maar ''kijk hoe streng wij zijn voor een auto bij jou op de oprit staat''.')
  on conflict (client_id) do update set sector = excluded.sector, volume = excluded.volume, doelen = excluded.doelen, doelgroepen = excluded.doelgroepen, kernboodschap = excluded.kernboodschap, updated_at = now();






end $$;
